activities.code:
def fact(n):
    if n == 1:
        return 1
    return n * fact(n - 1)
r = fact(3)

def show(n):
    if n == 0:
        return
    print(n)
    show(n - 1)
show(3)

def total(n):
    if n == 0:
        return 0
    return n + total(n - 1)
print(total(4))

def power(b, e):
    if e == 0:
        return 1
    return b * power(b, e - 1)
p = power(2, 3)

def countdown(n):
    if n == 0:
        return "go"
    return countdown(n)
print(countdown(3))

activities.solution:
def countdown(n):
    if n == 0:
        return "go"
    return countdown(n - 1)
print(countdown(3))

