def digits(n):
    if n < 10:
        return 1
    return 1 + digits(n // 10)
print(digits(4071))

def halvings(n):
    if n <= 1:
        return 0
    return 1 + halvings(n // 2)
print(halvings(16))

def rev(s):
    if s == "":
        return ""
    return rev(s[1:]) + s[0]
r = rev("abc")

def mult(a, b):
    if b == 0:
        return 0
    return a + mult(a, b - 1)
